from create_mds import rows,q,EL,AP,OL,MR,QU,MD,IP,IM,LU
from qbank_authoring import ref
MP=ref('NCI: Myeloproliferative Neoplasms Treatment—Health Professional PDQ','https://www.cancer.gov/types/myeloproliferative/hp/myeloproliferative-neoplasms-treatment')
CY=ref('CYTO-PV: Cardiovascular Events and Hematocrit-Control Intensity','https://www.nejm.org/doi/10.1056/NEJMoa1208500')
ET=ref('Blood: How I Treat Essential Thrombocythemia','https://ashpublications.org/blood/article/128/20/2403/35610/How-I-treat-essential-thrombocythemia')
MO=ref('FDA: Momelotinib Integrated Review and Mechanism','https://www.accessdata.fda.gov/drugsatfda_docs/nda/2023/216873Orig1s000IntegratedR.pdf')
q('A patient has sustained erythrocytosis, low serum EPO, JAK2 V617F and marrow panmyelosis. Which diagnosis is most likely?', 'Polycythemia vera',[
 ('Hypoxia-driven secondary erythrocytosis','The low EPO, driver mutation and panmyelosis favor a clonal process.'),('Relative erythrocytosis from dehydration alone','That does not explain the complete clonal marrow phenotype.'),('CML defined by JAK2','CML is defined by BCR::ABL1, not JAK2 alone.')],
 'An elevated Hb is a starting point, not the full diagnosis', '**PV is a clonal MPN with characteristic genetic and marrow findings.**',['Most cases have JAK2 V617F; exon 12 variants account for many remaining cases.','Low EPO is supportive within formal diagnostic criteria.'], '**Assess thrombosis risk and symptom burden.**',['Iron deficiency can mask the degree of erythrocytosis.','Review splenomegaly, aquagenic pruritus and microvascular symptoms.'],[['Genetics','JAK2 pathway'],['Marrow','Panmyelosis'],['EPO','Often low']],[MP],style='clinical_scenario')
q('Which pattern favors secondary erythrocytosis rather than PV?', 'Chronic hypoxemia with an appropriate EPO-driven response and no supporting clonal findings',[
 ('JAK2 mutation with marrow panmyelosis and low EPO','That supports PV.'),('A single high hematocrit during dehydration as proof of increased red-cell mass','Relative concentration must be considered.'),('Pruritus alone as definitive evidence of any specific cause','Symptoms are not individually diagnostic.')],
 'Distinguish true increased production from relative concentration', '**Hypoxia can stimulate renal EPO and red-cell production.**',['OSA, smoking-related carbon monoxide and cardiopulmonary disease may contribute.','EPO-producing lesions and drugs such as testosterone are other possibilities.'], '**Treat the cause and assess thrombosis management appropriately.**',['Do not automatically transfer every PV treatment rule to secondary erythrocytosis.','Persistent unexplained cases need hematological evaluation.'],[['Relative','Reduced plasma volume'],['Secondary','EPO or hypoxia-related production'],['PV','Clonal marrow disease']],[MP])
q('What hematocrit target is supported by CYTO-PV to reduce major thrombotic/cardiovascular outcomes in PV?', 'Below 45%',[
 ('45–50% as equally protective','The lower-target group had better relevant outcomes.'),('Above 55% to maximize oxygen carrying capacity','This can increase viscosity and thrombotic risk.'),('No target is needed if the platelet count is normal','Red-cell control remains important.')],
 'Hematocrit control is an outcome-based treatment goal', '**CYTO-PV compared less than 45% with 45–50%.**',['The stricter target reduced the combined major cardiovascular/thrombotic endpoint.','This complements other risk-reduction measures.'], '**Use phlebotomy and/or cytoreduction as indicated.**',['Low-dose aspirin is used when appropriate and not contraindicated.','Manage cardiovascular risk factors.'],[['Target','Hematocrit <45%'],['Methods','Phlebotomy and selected cytoreduction'],['Other care','Antithrombotic and risk-factor assessment']],[CY,MP])
q('Which factors conventionally place a PV patient in a higher thrombotic-risk group?', 'Older age, commonly over 60, or a prior thrombosis',[
 ('MCV alone','It does not define the conventional thrombotic-risk group.'),('Blood group alone','It is not the principal clinical risk classification.'),('A normal WBC count as proof of no thrombotic risk','Thrombosis risk is not excluded by that finding.')],
 'The treatment strategy is broader than the current hematocrit', '**Age and thrombosis history strongly influence cytoreductive decisions.**',['Symptoms and inadequate count control can also influence treatment.','Use the relevant risk framework rather than one isolated count.'], '**Choose cytoreduction according to the patient.**',['Hydroxyurea and interferon-based approaches have important roles.','Pregnancy planning, tolerability and treatment goals affect selection.'],[['Core risk','Age and thrombosis history'],['Additional needs','Symptoms and control'],['Choice','Individualized cytoreductive strategy']],[MP])
q('A patient has persistent thrombocytosis after iron deficiency and inflammation have been excluded. Which driver set is associated with ET and primary myelofibrosis?', 'JAK2, CALR or MPL',[
 ('PML::RARA only','That defines classical APL.'),('BCR::ABL1 as the defining ET driver','It defines a different MPN pathway and must be excluded when appropriate.'),('A single HFE variant as confirmation','That does not establish ET.')],
 'A driver mutation supports clonality but does not alone establish the exact MPN', '**JAK2, CALR and MPL are major driver categories.**',['Some cases are triple negative.','Marrow morphology distinguishes ET from prefibrotic MF and other disorders.'], '**Integrate the full diagnostic criteria.**',['Reactive causes must still be reviewed.','A mutation result should not replace an adequate marrow and clinical assessment.'],[['Drivers','JAK2 / CALR / MPL'],['Morphology','Defines the specific MPN pattern'],['Exclusions','Reactive and other clonal causes']],[MP,ET])
q('Why is marrow morphology important in a thrombocytosis work-up with a CALR mutation?', 'It helps distinguish ET from prefibrotic primary myelofibrosis, which have different clinical implications',[
 ('CALR alone uniquely defines ET','CALR can occur in more than one MPN.'),('A platelet count alone identifies the marrow fibrosis grade','It cannot do that.'),('The morphology is irrelevant once any mutation is found','The integrated disease category still matters.')],
 'Shared drivers can underlie different marrow architectures', '**Megakaryocyte morphology, distribution and accompanying cellularity contribute to classification.**',['Prefibrotic MF can present with marked thrombocytosis.','Anemia, leukocytosis, LDH and splenic findings provide additional context.'], '**Use expert hematopathological integration.**',['Avoid assuming that a minimally fibrotic marrow cannot have prefibrotic MF.','Prognosis and follow-up differ by the correct diagnosis.'],[['Mutation','Clonal pathway clue'],['Marrow','ET versus prefibrotic pattern'],['Clinical impact','Risk and management differences']],[MP,ET])
q('An ET patient has platelets 1,700 × 10^9/L and mucosal bleeding. Which mechanism should be assessed before prescribing aspirin?', 'Acquired von Willebrand syndrome',[
 ('A high count guarantees protection from bleeding','Extreme thrombocytosis can paradoxically associate with bleeding.'),('Hemophilia A proven by platelet count alone','That is not the mechanism established by this count.'),('Aspirin must be increased automatically because platelets are high','Antiplatelet therapy can worsen bleeding in this setting.')],
 'Platelet number and hemostatic function are not interchangeable', '**Loss of high-molecular-weight VWF multimers can occur with extreme thrombocytosis.**',['Assess VWF activity and the clinical bleeding pattern.','The thrombotic and bleeding risks must both be considered.'], '**Avoid reflex aspirin in active bleeding or significant acquired VWF dysfunction.**',['Cytoreduction can improve the underlying count-related mechanism.','Use specialist hemostatic management when bleeding is important.'],[['Count','Extremely high'],['Paradox','Bleeding risk'],['Test concern','Acquired VWF dysfunction']],[ET],style='clinical_scenario')
q('A young pregnant patient with ET needs cytoreduction after specialist risk assessment. Which agent class is generally preferred when cytoreduction is required in pregnancy?', 'Interferon alfa',[
 ('Hydroxyurea as an automatic preferred pregnancy drug','Pregnancy requires an alternative safety-focused strategy.'),('Anagrelide as the universal first choice during pregnancy','It is not the usual preferred pregnancy cytoreductive option.'),('No cytoreduction can ever be used in pregnancy','Treatment can be indicated for selected high-risk situations.')],
 'Pregnancy changes the choice of cytoreductive agent', '**Interferon is commonly used when cytoreduction is necessary.**',['The decision requires hematology and obstetric collaboration.','Antithrombotic management depends on history and bleeding risk.'], '**Plan treatment before conception when possible.**',['Review previous thrombosis, pregnancy complications and VWF status.','Avoid a one-size-fits-all aspirin or anticoagulation rule.'],[['Cytoreductive class','Interferon'],['Assessment','Maternal and fetal risk'],['Other care','Individual antithrombotic plan']],[ET],style='clinical_scenario')
q('A patient has massive splenomegaly, anemia, teardrop cells, leukoerythroblastosis and a fibrotic marrow with atypical megakaryocytes. Which diagnosis is a major consideration?', 'Primary myelofibrosis',[
 ('Isolated iron deficiency','It does not account for the full marrow and splenic pattern.'),('Pure red-cell aplasia','That is selective erythroid failure rather than fibrotic architectural disruption.'),('Uncomplicated immune thrombocytopenia','That does not explain this multilineage smear and marrow pattern.')],
 'Fibrotic marrow disease can shift hematopoiesis to extramedullary sites', '**Splenic enlargement and a leukoerythroblastic smear are characteristic clues.**',['Driver and additional mutations contribute to diagnosis and prognosis.','Exclude secondary/reactive fibrosis and post-PV or post-ET MF.'], '**Risk-stratify before selecting therapy.**',['Symptoms, anemia, counts and molecular features matter.','Treatment ranges from supportive and JAK-directed care to transplant in selected patients.'],[['Marrow','Fibrosis with atypical megakaryocytes'],['Blood','Teardrops and immature cells'],['Spleen','Extramedullary hematopoietic burden']],[MP],style='clinical_scenario')
q('What is a major goal of JAK-inhibitor treatment such as ruxolitinib in appropriate myelofibrosis?', 'Reduction of symptomatic splenomegaly and constitutional symptom burden',[
 ('Guaranteed eradication of every malignant stem cell','JAK inhibition is not a universal curative strategy.'),('Correction of every anemia regardless of agent','Some JAK inhibitors can worsen cytopenias and agent selection matters.'),('Elimination of the need for risk assessment','Risk and transplant suitability remain important.')],
 'Symptom control and disease eradication are different treatment goals', '**JAK-pathway inhibition can improve splenic and systemic symptoms.**',['Counts, anemia and prior therapy influence drug choice.','Infection and drug-specific toxicities require monitoring.'], '**Do not delay transplant assessment in a suitable high-risk patient.**',['Allogeneic transplantation remains the major potentially curative option.','Reassess benefit and progression over time.'],[['JAK inhibition','Symptoms and spleen response'],['Limits','Not universal clone eradication'],['Higher-risk disease','Consider transplant pathway']],[MP])
q('Which mechanistic feature helps explain momelotinib’s anemia-related role in myelofibrosis?', 'ACVR1 inhibition with effects on hepcidin, in addition to JAK1/JAK2 inhibition',[
 ('Direct iron chelation as its only action','That is not its mechanism.'),('Selective CD20 depletion','That describes a different drug class.'),('Direct replacement of endogenous EPO by a recombinant hormone','Momelotinib is a kinase inhibitor.')],
 'Iron regulation can be targeted alongside inflammatory signaling', '**ACVR1-related hepcidin suppression can improve iron availability for erythropoiesis.**',['The US indication includes intermediate/high-risk MF in adults with anemia.','The patient’s platelet count, symptoms and prior therapy remain relevant.'], '**Apply the current agent-specific safety plan.**',['Review infections, hepatic function and interactions.','A mechanistic advantage does not guarantee a response in every anemia.'],[['Targets','JAK1/JAK2 and ACVR1'],['Iron pathway','Hepcidin modulation'],['Population','Appropriate MF with anemia']],[MO])
q('A patient with a known Philadelphia-negative MPN develops new cytopenias, rising blasts and constitutional decline. What is the best next step?', 'Urgent reassessment for disease progression or leukemic transformation with marrow and genetic evaluation',[
 ('Assume all new symptoms are benign medication effects without assessment','Progression is an important competing explanation.'),('Keep the prior risk category permanently unchanged','Disease risk evolves.'),('Use a normal past marrow to exclude current transformation','The current state requires reassessment.')],
 'An MPN can evolve beyond its original phenotype', '**New counts, blasts or symptoms can signal progression.**',['Drug toxicity, infection and nutritional causes may also contribute.','Marrow morphology and genetics help distinguish mechanisms.'], '**Reconsider the treatment goal and urgency.**',['Advanced disease may require a different therapy or transplant discussion.','Continue supportive care while the diagnosis is clarified.'],[['Trigger','New cytopenias or blasts'],['Assessment','Marrow and updated genetics'],['Decision','Revised risk and treatment strategy']],[MP],style='clinical_scenario')
